buggyCode:
class MetricsClient {
    private volatile Conn conn = new Conn(1);

    void start(ScheduledExecutorService scheduler) {
        scheduler.scheduleAtFixedRate(conn::send, 0, 10, TimeUnit.SECONDS);
    }

    void reconnect() {
        conn = new Conn(conn.id + 1);
    }
}

// Mô phỏng: tạo task, reconnect, rồi chạy task
Runnable task = client.conn::send;
client.reconnect();
task.run();

fix.code:
void start(ScheduledExecutorService scheduler) {
    scheduler.scheduleAtFixedRate(() -> conn.send(), 0, 10, TimeUnit.SECONDS);
}
// hoặc: scheduleAtFixedRate(this::sendCurrent, ...) với
// void sendCurrent() { conn.send(); }
